use vstd::prelude::*;

verus! {

    // A pure spec‐function that inserts x at position idx in sequence s.
    // If idx ≥ s.len(), it just appends x.
    spec fn seq_insert<T: Copy>(s: Seq<T>, idx: nat, x: T) -> Seq<T>
        decreases s, idx
    {
        if idx >= s.len() {
            s + Seq(x)
        } else {
            s[..idx] + Seq(x) + s[idx..]
        }
    }

    // Insert a value into a Vec<T> at position idx, shifting later elements right.
    // We require T: Copy so that we can reason about views as Seqs.
    fn numpy_insert<T: Copy>(mut arr: Vec<T>, idx: usize, value: T) -> (result: Vec<T>)
        requires
            // idx must be in [0, arr.len()]
            idx <= arr.len(),
        ensures
            // length grows by exactly 1
            result.len() == old(arr).len() + 1,
        ensures
            // the new view is exactly the old view with value inserted at idx
            result.view() == seq_insert(old(arr).view(), idx as nat, value),
    {
        // split_off takes elements at positions idx..end into a new Vec
        let mut right = arr.split_off(idx);
        // now arr has the first idx elements
        arr.push(value);
        // append the old suffix back after the inserted value
        arr.append(&mut right);
        arr
    }

} // end verus!

